package ug.audiocity.studio;
import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;
public final class UserDrumPacksTests {
 static int n;static void ok(boolean b,String why){n++;if(!b)throw new AssertionError(why);}static void clean(File f){if(f.isDirectory()){File[] fs=f.listFiles();if(fs!=null)for(File c:fs)clean(c);}f.delete();}
 static void le(OutputStream out,int value,int bytes)throws Exception{for(int i=0;i<bytes;i++)out.write(value>>>(8*i)&255);}
 static byte[] wav(int rate,int bits,int channels,int format)throws Exception{int frames=rate/10,align=channels*bits/8,size=frames*align;ByteArrayOutputStream out=new ByteArrayOutputStream();out.write("RIFF".getBytes("US-ASCII"));le(out,36+size,4);out.write("WAVEfmt ".getBytes("US-ASCII"));le(out,16,4);le(out,format,2);le(out,channels,2);le(out,rate,4);le(out,rate*align,4);le(out,align,2);le(out,bits,2);out.write("data".getBytes("US-ASCII"));le(out,size,4);for(int i=0;i<frames;i++)for(int c=0;c<channels;c++){double sample=Math.sin(i*.13)*.3;int value=format==3?Float.floatToIntBits((float)sample):(int)(sample*(bits==16?32767:bits==24?8388607:2147483647));le(out,value,bits/8);}return out.toByteArray();}
 static byte[] zip(String[] names,byte[][] data)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(out)){for(int i=0;i<names.length;i++){zip.putNextEntry(new ZipEntry(names[i]));zip.write(data[i]);zip.closeEntry();}}return out.toByteArray();}
 static int count(File app)throws Exception{return UserDrumPacks.list(app).size();}
 public static void main(String[] args)throws Exception{File root=Files.createTempDirectory("acs-user-drums-").toFile();try{File app=new File(root,"app"),project=new File(root,"project");app.mkdir();project.mkdir();byte[] pcm16=wav(48000,16,2,1),pcm24=wav(44100,24,1,1),float32=wav(96000,32,2,3);
  UserDrumPacks.Info single=UserDrumPacks.install(new ByteArrayInputStream(pcm24),"My Kick.wav",app);ok(single.sounds.size()==1&&single.sounds.get(0).category.equals("Kick"),"any supported named WAV imports and is categorized by its real name");float[] resampled=UserDrumPacks.preview(app,single,single.sounds.get(0));ok(resampled.length==9600&&Math.abs(resampled[200])>.001,"44.1 kHz mono 24-bit WAV becomes an audible 48 kHz stereo drum source");
  byte[] archive=zip(new String[]{"Kicks/Kick 01.wav","Snares/Snare 02.WAV","Hats/Open Hat.wav","LICENSE.txt","broken.sfz"},new byte[][]{pcm16,pcm24,float32,"保留许可和作者\nKeep the author's terms".getBytes("UTF-8"),"unrelated SFZ is not a drum sample".getBytes("UTF-8")});UserDrumPacks.Info pack=UserDrumPacks.install(new ByteArrayInputStream(archive),"My producer drums.zip",app);ok(pack.sounds.size()==3&&count(app)==2,"ZIP imports all WAVs in nested folders and ignores unrelated mapping files");ok(pack.sounds.stream().anyMatch(s->s.name.contains("Kicks/")&&s.category.equals("Kick"))&&pack.sounds.stream().anyMatch(s->s.category.equals("Hat")),"folder labels and useful categories survive import");UserDrumPacks.Info again=UserDrumPacks.install(new ByteArrayInputStream(archive),"My producer drums.zip",app);ok(again.id.equals(pack.id)&&count(app)==2,"re-importing the same pack is idempotent");for(UserDrumPacks.Sound sound:pack.sounds)ok(UserDrumPacks.preview(app,pack,sound).length==9600,"16/24/float32 rates all decode at the correct duration");
  UserDrumPacks.Sound selected=pack.sounds.get(0);Core.Session session=new Core.Session();session.directory=project.getAbsolutePath();session.bpm=240;BeatPilotDrumPattern p=new BeatPilotDrumPattern(240,1);float[] wave=UserDrumPacks.choose(app,project,pack,selected);for(int lane=0;lane<8;lane++){p.setImported(lane,selected.file,selected.name);p.set(0,lane,lane,90+lane);}ok(p.encode().startsWith("v5|"),"generic sound references use the new backward-compatible grid format");BeatPilotDrumPattern decoded=BeatPilotDrumPattern.decode(p.encode());for(int lane=0;lane<8;lane++){ok(decoded.imported(lane)&&decoded.userFile(lane).equals(selected.file)&&decoded.sampleName(lane).equals(selected.name),"one user sample can be assigned to any drum lane and survives encode");ok(p.resizedEmpty(4).userFile(lane).equals(selected.file)&&PatternLibrary.lane(p,lane).userFile(lane).equals(selected.file),"resizing and independent lane printing preserve source choice");}ok(BeatPilotDrumPattern.decode(BeatPilotDrumRollData.retempo(p.encode(),100)).userFile(0).equals(selected.file),"tempo changes retain the selected user waveform");
  PatternLibrary.Entry entry=PatternLibrary.add(session,"My imported beat",p);PatternLibrary.Entry copy=PatternLibrary.duplicate(session,entry.id);ok(PatternLibrary.pattern(session,copy).userFile(0).equals(selected.file),"copied patterns retain their independent sample references");float[][] kit=new float[8][];Arrays.fill(kit,wave);PatternArrangement.place(session,entry.id,kit,0,1);ok(ProjectIO.files(session).contains(selected.file),"chosen sounds are included in portable project dependencies");ByteArrayOutputStream backup=new ByteArrayOutputStream();AudioIO.backup(backup,session);File restore=new File(root,"restore");restore.mkdir();Core.Session reopened=AudioIO.restore(new ByteArrayInputStream(backup.toByteArray()),restore);clean(new File(app,"drum_packs"));BeatPilotDrumPattern restored=PatternLibrary.pattern(reopened,reopened.patterns.get(0));float[] portable=UserDrumPacks.load(restore,app,restored.userFile(0));ok(Arrays.equals(wave,portable),"restored project plays the exact personal sample without the installed pack");ok(reopened.tracks.size()==8&&restored.sampleName(0).equals(selected.name),"sample names and separate channels survive reopen and backup");
  decoded.setSampleChoice(0,DrumSampleCatalog.defaultIndex(0));ok(!decoded.imported(0)&&decoded.imported(1),"switching one lane back to a factory sound leaves other user choices intact");
  int before=count(app);for(byte[] bad:new byte[][]{zip(new String[]{"../escape.wav"},new byte[][]{pcm16}),zip(new String[]{"bad.wav"},new byte[][]{new byte[]{1,2,3}}),zip(new String[]{"README.txt"},new byte[][]{"No WAV".getBytes("UTF-8")})}){try{UserDrumPacks.install(new ByteArrayInputStream(bad),"Bad pack.zip",app);throw new AssertionError("bad import accepted");}catch(IOException expected){n++;}ok(count(app)==before,"failed imports leave no partial pack or changes to existing packs");}
  try{decoded.setImported(0,"../../outside.acpack","bad");throw new AssertionError("unsafe ref accepted");}catch(IllegalArgumentException expected){n++;}try{BeatPilotDrumPattern.decode(p.encode().replace(selected.file,"../../outside.acpack"));throw new AssertionError("unsafe project ref accepted");}catch(IllegalArgumentException expected){n++;}try{UserDrumPacks.install(new ByteArrayInputStream(pcm16),"unsupported.rar",app);throw new AssertionError("RAR silently accepted");}catch(IOException expected){ok(expected.getMessage().contains("WAV"),"unsupported formats explain the supported import choices");}
  System.out.println("UserDrumPacksTests passed "+n+" checks");
 }finally{clean(root);}}
}
